DELETE FROM notas WHERE aluno_id NOT IN (SELECT id FROM alunos); DELETE FROM acompanhamentos WHERE aluno_id NOT IN (SELECT id FROM alunos); DELETE FROM responsavel_usuario WHERE responsavel_id NOT IN (SELECT id FROM responsaveis); DELETE FROM responsavel_usuario WHERE usuario_id NOT IN (SELECT id FROM usuarios); DELETE FROM responsaveis WHERE cpf IN ('92233344455','92266677788'); SELECT (SELECT COUNT(*) FROM responsaveis WHERE cpf IN ('92233344455','92266677788')) AS resp_orfaos, (SELECT COUNT(*) FROM notas) AS notas, (SELECT COUNT(*) FROM acompanhamentos) AS acomp, (SELECT COUNT(*) FROM responsavel_usuario) AS vinculos, (SELECT COUNT(*) FROM usuarios) AS usuarios;